use crate::policy::Role;

/// Role-less documentation view of the top-level `config` group. It keeps the
/// historical superset: read-only rows plus a pointer at the human-operator
/// write surface. A resolved role never receives this text.
const CONFIG_SUPERSET: &str = "Local configuration for {}:\n\n  show               Print a redacted snapshot of the local configuration file\n  provider get       Print the persisted machine-wide default provider (null when unset)\n\nWrites live under the human-operator admin group (AI roles must never invoke it):\n  admin config set SETTING [VALUE|--stdin] [--target-role ROLE]  Persist a setting (canonical PHASEGENT_* names or kebab-case aliases; secrets require --stdin or prompt, except notify-email-password which also accepts a direct value)\n  admin config clear SETTING [--target-role ROLE]                Remove a persisted setting\n  admin config provider set NAME            Validate and persist the machine-wide default provider (redmine, local, forgejo, or gitlab)\n  admin config provider clear               Remove the persisted machine-wide default provider\n  admin config migrate --from-sqlite PATH [--from-toml PATH]      Move a legacy SQLite/TOML configuration into the configuration file\n\nUse 'phasegent --help config <subcommand>' for options.\n`config show` and `config provider get` do not require a role because the global default and the global settings are machine-wide; `admin config set/clear` for global settings also works without a role. An ordinary human Operator runs without a role and writes role-scoped settings to the admin scope by default; `--target-role ROLE` selects the configuration entry for one role and never the caller's identity. A verified agent or a managed session without a role cannot use the admin write surface. PHASEGENT_ROLE is a legacy marker only and grants no identity. See docs/cli-caller-context.md.\n\nAll settings and credentials live in one JSONC configuration file. Effective precedence per field is CLI flags > PHASEGENT_* environment > the configuration file > built-in defaults. `admin config set`/`clear` write that file only. Override the file location with an absolute PHASEGENT_CONFIG_PATH; the default is the ProjectDirs config_dir phasegent.jsonc. The directory must be private to the owner and the file readable/writable by the owner only. A legacy phasegent.toml is not read at runtime; it is accepted only as an input of `admin config migrate`, which moves a legacy SQLite/TOML configuration into the file and then purges the migrated rows from the legacy database.\n\nIndex backend is URL-driven: a non-empty secret `PHASEGENT_INDEX_PG_URL` (`index-pg-url`, env overrides persisted) selects PostgreSQL, absent or blank selects SQLite. Use `admin config set index-pg-url --stdin` for Postgres and `admin config clear index-pg-url` to return to SQLite. `PHASEGENT_INDEX_BACKEND` (`index-backend`) is legacy, ignored for selection, and kept only for compatibility. PostgreSQL uses tsvector + GIN, auto-applies migrations from `migrations/pg/0001_issue_index.sql`, and never stores credentials.\n\nAgent notifications use one global setting per channel field (env overrides the configuration file). Enable with `admin config set notify-enabled true` and `admin config set notify-channel <ntfy|webhook|dingtalk|email>`, then per-channel fields (notify-ntfy-base-url, notify-ntfy-topic, notify-webhook-url, ...). Email fields are notify-email-smtp-host, notify-email-smtp-port, notify-email-tls, notify-email-username, notify-email-password, notify-email-from, notify-email-to, and notify-email-reply-to; notify-email-tls accepts auto (the unset default), implicit, starttls, or plain. Secrets (notify-ntfy-token, notify-webhook-token, notify-dingtalk-secret, notify-email-password) require --stdin and stay write-only, except notify-email-password which also accepts a direct value and is then visible in shell history and process listings.\n";

/// Role-specific view of the top-level `config` group: read-only rows plus the
/// shared precedence notes, without any admin write flag or secret-setting
/// usage.
fn config_role_text(role: Role) -> String {
    format!(
        "Local configuration for {role}:\n\n  show               Print a redacted snapshot of the local configuration file\n  provider get       Print the persisted machine-wide default provider (null when unset)\n\nWrites live under the human-operator admin group (AI roles must never invoke it); read-only views stay top-level.\n\nUse 'phasegent --help config <subcommand>' for options.\n`config show` and `config provider get` do not require a role because the global default and the global settings are machine-wide.\n\nAll settings and credentials live in one JSONC configuration file. Effective precedence per field is CLI flags > PHASEGENT_* environment > the configuration file > built-in defaults. A legacy phasegent.toml is not read at runtime; it is accepted only as an input of `admin config migrate`, which moves a legacy SQLite/TOML configuration into the file and then purges the migrated rows from the legacy database. Override the file location with an absolute PHASEGENT_CONFIG_PATH; the default is the ProjectDirs config_dir phasegent.jsonc.\n\nIndex backend is URL-driven: a non-empty secret `PHASEGENT_INDEX_PG_URL` (`index-pg-url`, env overrides persisted) selects PostgreSQL, absent or blank selects SQLite. `PHASEGENT_INDEX_BACKEND` (`index-backend`) is legacy, ignored for selection, and kept only for compatibility. PostgreSQL uses tsvector + GIN, auto-applies migrations from `migrations/pg/0001_issue_index.sql`, and never stores credentials."
    )
}

pub(crate) fn print_config_help(role: Option<Role>) {
    match role {
        None => println!("{}", CONFIG_SUPERSET.replacen("{}", "all roles", 1)),
        Some(role) => println!("{}", config_role_text(role)),
    }
}

pub(crate) fn print_config_command_help(role: Option<Role>, command: &str) {
    match command {
        "show" => {
            println!(
                "Usage: phasegent [config show]\n\nPrints a compact JSON snapshot of the local configuration file:\n  config_path               absolute path to the JSONC configuration file\n  roles                      array with one entry per role (admin, orchestrator, executor, reviewer, explore), each with its provider, the role-scoped Redmine close-status id, and credential presence/length\n  global_settings            array of PHASEGENT_REDMINE_API_BASE (the one machine-wide Redmine REST address), PHASEGENT_REDMINE_GIT_MIRROR_API_KEY, PHASEGENT_REDMINE_REPOSITORY_URL, PHASEGENT_DEFAULT_PROVIDER, PHASEGENT_INDEX_BACKEND, PHASEGENT_INDEX_PG_URL, plus PHASEGENT_NOTIFY_* channel fields\n  global_default_provider    machine-wide default provider literal (redmine, local, forgejo, or gitlab); null when unset\n\nThe Redmine REST address is machine-wide, so it appears once in global_settings and never inside a role entry. Credential entries report presence and length only; the bearer key for the git mirror plugin, the index PG URL, and notify secrets (ntfy-token, webhook-token, dingtalk-secret, email-password) are also reported as presence/length, and URL overrides (Redmine API base, repository URL, ntfy-base-url, webhook-url, dingtalk-webhook-url) are sanitised so embedded userinfo is stripped before the snapshot is rendered. The machine-wide default provider is a non-secret literal rendered both as a top-level field and inside `global_settings` so the snapshot stays self-contained. The legacy index backend literal is also rendered inside `global_settings` for compatibility but is ignored for selection; only `PHASEGENT_INDEX_PG_URL` presence selects PostgreSQL. Notify non-URL fields report presence/length only; notify precedence is env over the configuration file.\n\nThe snapshot reflects the configuration file only; a PHASEGENT_* environment override shadows a value at resolve time but is not shown. The Redmine REST address additionally resolves from the PHASEGENT_REDMINE_API_BASE/PHASEGENT_API_BASE environment variables before the persisted value. Effective precedence is CLI flags > PHASEGENT_* environment > the configuration file > built-in defaults.\n\nA verified agent role restricts the roles array to that role; an unmarked Operator sees every role. A legacy PHASEGENT_ROLE marker grants no filter and no identity."
            );
        }
        // The write pages moved under `admin config`; delegate so any legacy
        // `config set/clear --help` parse path lands on the admin-scoped page,
        // which the topic gate already denies for a non-admin role.
        "set" | "clear" => print_admin_config_command_help(role, command),
        _ => print_config_help(role),
    }
}

/// Role-less documentation view of the top-level `config provider` group.
const CONFIG_PROVIDER_SUPERSET: &str = "Machine-wide default provider:\n\n  get               Print the persisted PHASEGENT_DEFAULT_PROVIDER (null when unset)\n  set NAME          Validate and persist the default (redmine, local, forgejo, or gitlab)\n  clear             Remove the persisted default so the resolver falls back to the role-scoped provider\n\n`config provider get` does not require a role because the default is global; `admin config provider set`/`clear` are human-operator only. The resolver precedence is: explicit --provider > PHASEGENT_PROVIDER (env) > PHASEGENT_DEFAULT_PROVIDER (env) > the persisted PHASEGENT_DEFAULT_PROVIDER in the configuration file > the role-scoped provider in the configuration file > redmine fallback. `admin config provider set`/`clear` write the configuration file only. A Forgejo or GitLab default selects the provider only, not a repository: each operation resolves an explicit --repository, an origin that attests the role's trusted instance, or the stored default outside Git.";

/// Role-specific view: only the read-only `get` row, plus the resolver chain
/// (which is not admin-sensitive). The write rows live on the admin group page.
fn config_provider_role_text(role: Role) -> String {
    format!(
        "Machine-wide default provider ({role}):\n\n  get               Print the persisted PHASEGENT_DEFAULT_PROVIDER (null when unset)\n\n`config provider get` does not require a role because the default is global. Writes to the machine-wide default are human-operator only and live under the admin group (AI roles must never invoke it). The resolver precedence is: explicit --provider > PHASEGENT_PROVIDER (env) > PHASEGENT_DEFAULT_PROVIDER (env) > the persisted PHASEGENT_DEFAULT_PROVIDER in the configuration file > the role-scoped provider in the configuration file > redmine fallback."
    )
}

pub(crate) fn print_config_provider_help(role: Option<Role>) {
    match role {
        None => println!("{CONFIG_PROVIDER_SUPERSET}"),
        Some(role) => println!("{}", config_provider_role_text(role)),
    }
}

pub(crate) fn print_config_provider_command_help(role: Option<Role>, command: &str) {
    match command {
        "get" => {
            println!(
                "Usage: phasegent config provider get\n\nPrints a JSON object with the persisted PHASEGENT_DEFAULT_PROVIDER literal (`redmine`, `local`, or `forgejo`) or `null` when the default has never been set. The output never echoes any secret value. The snapshot is the configuration file only; effective resolution still applies the environment before this value."
            );
        }
        // Provider writes moved under `admin config provider`; keep the admin
        // gate on the delegated page.
        "set" | "clear" => print_admin_config_provider_command_help(role, command),
        _ => print_config_provider_help(role),
    }
}

/// `admin config` group page: the human-operator write surface, reachable only
/// after the topic gate admits `admin` (never an AI role).
pub(crate) fn print_admin_config_help(role: Option<Role>) {
    let role_text = role.map_or("ROLE", Role::as_str);
    println!(
        "Human-operator setting writes for {role_text}:\n\n  phasegent admin config set SETTING [VALUE|--stdin] [--target-role ROLE]  Persist a setting (canonical PHASEGENT_* names or kebab-case aliases; secrets require --stdin or prompt, except notify-email-password which also accepts a direct value)\n  phasegent admin config clear SETTING [--target-role ROLE]                Remove a persisted setting\n  phasegent admin config provider set NAME            Validate and persist the machine-wide default provider (redmine, local, forgejo, or gitlab)\n  phasegent admin config provider clear               Remove the persisted machine-wide default provider\n  phasegent admin config migrate --from-sqlite PATH [--from-toml PATH]      Move a legacy SQLite/TOML configuration into the configuration file\n\nUsage: phasegent admin config <subcommand>\n\nAdmin config writes the JSONC configuration file only. Global settings (mirror key, Redmine API base, repository URL, default provider, index pg-url) are machine-wide and work without a role; a role-scoped write uses the admin scope for an ordinary Operator by default and accepts --target-role admin|orchestrator|executor|reviewer|explore to select one role's configuration entry. --target-role is rejected for global settings, and no verified agent or managed session without a role may use this surface. The Redmine REST address is one machine-wide value: `redmine-api-base` sets it for every role and never creates a per-role address. Secret settings never accept a direct value: pass --stdin or use the secure prompt. The one exception is notify-email-password, which also accepts a direct value because SMTP providers hand it out as a pasteable API token; that value then appears in shell history and process listings, so pass --stdin when that exposure matters.\n\nThe configuration file is a single JSONC document: the directory must be private to the owner and the file readable and writable by the owner only. Override the location with an absolute PHASEGENT_CONFIG_PATH; the default is the ProjectDirs config_dir phasegent.jsonc. A legacy phasegent.toml is not read at runtime; it is an input of `admin config migrate` only.\n\nUse 'phasegent --help admin config set|clear|migrate' for the full setting list and examples."
    );
}

pub(crate) fn print_admin_config_command_help(role: Option<Role>, command: &str) {
    match command {
        "set" => {
            println!(
                "Usage: phasegent admin config set <SETTING> [VALUE|--stdin] [--target-role ROLE]\n\nHuman-operator only; AI roles must never invoke the admin group.\n\nPersists a single setting in the JSONC configuration file. The value is never echoed in output.\n\nSupported settings (canonical name and kebab-case alias):\n  PHASEGENT_PROVIDER / provider\n  PHASEGENT_REDMINE_API_BASE / redmine-api-base    (machine-wide Redmine REST address, one value for every role)\n  PHASEGENT_REDMINE_CLOSE_STATUS_ID / redmine-close-status-id\n  PHASEGENT_CLOSE_STATUS_ID / close-status-id      (generic Redmine alias)\n  PHASEGENT_REDMINE_GIT_MIRROR_API_KEY / redmine-git-mirror-api-key   (secret)\n  PHASEGENT_REDMINE_REPOSITORY_URL / redmine-repository-url\n  PHASEGENT_DEFAULT_PROVIDER / default-provider      (validated through ProviderKind)\n  PHASEGENT_INDEX_BACKEND / index-backend            (legacy, ignored for selection)\n  PHASEGENT_INDEX_PG_URL / index-pg-url              (secret; presence selects PostgreSQL)\n\nNotify channel fields (one entry per field; secrets need --stdin):\n  PHASEGENT_NOTIFY_ENABLED / notify-enabled, PHASEGENT_NOTIFY_CHANNEL / notify-channel,\n  PHASEGENT_NOTIFY_NTFY_BASE_URL / notify-ntfy-base-url, PHASEGENT_NOTIFY_NTFY_TOPIC / notify-ntfy-topic,\n  PHASEGENT_NOTIFY_NTFY_TOKEN / notify-ntfy-token (secret), PHASEGENT_NOTIFY_WEBHOOK_URL / notify-webhook-url,\n  PHASEGENT_NOTIFY_WEBHOOK_TOKEN / notify-webhook-token (secret), plus dingtalk fields\n  PHASEGENT_NOTIFY_EMAIL_SMTP_HOST / notify-email-smtp-host   (bare hostname)\n  PHASEGENT_NOTIFY_EMAIL_SMTP_PORT / notify-email-smtp-port\n  PHASEGENT_NOTIFY_EMAIL_TLS / notify-email-tls               (auto, implicit, starttls, plain)\n  PHASEGENT_NOTIFY_EMAIL_USERNAME / notify-email-username     (any nonempty SMTP username)\n  PHASEGENT_NOTIFY_EMAIL_PASSWORD / notify-email-password     (secret)\n  PHASEGENT_NOTIFY_EMAIL_FROM / notify-email-from, PHASEGENT_NOTIFY_EMAIL_TO / notify-email-to,\n  PHASEGENT_NOTIFY_EMAIL_REPLY_TO / notify-email-reply-to\n\nEmail TLS resolves automatically when unset or set to auto: port 465 uses implicit TLS and every other explicit port (for example 587 or 25) requires STARTTLS, with no port defaulting to STARTTLS on 587. Explicit implicit, starttls, or plain override the port and keep their existing meaning. Cloudflare Email Sending uses smtp.mx.cloudflare.net:465 with the literal username api_token and the API token as the password:\n  phasegent admin config set notify-email-smtp-host smtp.mx.cloudflare.net\n  phasegent admin config set notify-email-smtp-port 465\n  phasegent admin config set notify-email-username api_token\n  phasegent admin config set notify-email-password --stdin < /secure/path/cf-api-token\n  phasegent admin config set notify-email-from alerts@example.com\n  phasegent admin config set notify-email-to ops@example.com\n\nProject-id settings and provider-specific settings not listed above (such as the legacy\ngitlab-* keys) are rejected as unknown settings; use explicit --project-id per invocation instead. Secret settings follow the source policy below.\n\nSecret settings (redmine-git-mirror-api-key, index-pg-url, notify-ntfy-token, notify-webhook-token, notify-dingtalk-secret, notify-email-password) do not accept a direct value except notify-email-password:\n  phasegent admin config set redmine-git-mirror-api-key            # secure prompt\n  phasegent admin config set redmine-git-mirror-api-key --stdin    # read from stdin\n  phasegent admin config set index-pg-url --stdin < /secure/path/pg-url\n  phasegent admin config set notify-email-password --stdin < /secure/path/cf-api-token\n  phasegent admin config set notify-email-password CF_API_TOKEN_VALUE # direct value stays in argv, history, and process listings\n\nNon-secret settings use a positional value or --stdin. Index selection is URL-driven (no index-backend value needed):\n  phasegent admin config set redmine-api-base https://redmine.example   # machine-wide, no role needed\n  phasegent admin config set redmine-close-status-id 5 --target-role executor\n  phasegent admin config set index-pg-url --stdin < /secure/path/pg-url  # select PostgreSQL\n  phasegent admin config clear index-pg-url  # return to SQLite (index-backend is legacy, ignored)\n\nGlobal settings (mirror key, Redmine API base, repository URL, default provider, index pg-url) are machine-wide and work without a role;\nrole-scoped writes use the admin scope for an ordinary Operator by default and accept --target-role to select one role's configuration entry (a verified agent or managed session without a role cannot use this surface). The Redmine REST address is the machine-wide `redmine-api-base` value and never creates a per-role address. `admin config set default-provider` reuses the same validation as `admin config provider set`; `index-backend` is legacy, validated when set but ignored for selection. `admin config set` writes the JSONC configuration file only; the file location is the absolute PHASEGENT_CONFIG_PATH when set, otherwise the ProjectDirs config_dir phasegent.jsonc. Effective precedence is CLI flags > PHASEGENT_* environment > the configuration file > built-in defaults. Stable non-secret settings may be edited directly in that file; credentials live there too, so keep the file private to the owner."
            );
        }
        "clear" => {
            println!(
                "Usage: phasegent admin config clear <SETTING> [--target-role ROLE]\n\nHuman-operator only; AI roles must never invoke the admin group.\n\nRemoves the persisted setting from the JSONC configuration file. Prints the canonical setting name and whether a field was cleared.\n\nGlobal settings are machine-wide and can be cleared without a role: clearing `redmine-api-base` removes the single Redmine REST address every role shares. A role-scoped clear uses the admin scope for an ordinary Operator by default and accepts --target-role to select one role's configuration entry; --target-role is rejected for global settings, and no verified agent or managed session without a role may use this surface.\nThe bearer key (`redmine-git-mirror-api-key`), index PG URL, and notify secrets (`notify-ntfy-token`, `notify-webhook-token`, `notify-dingtalk-secret`, `notify-email-password`) are reported only as presence/length in `config show`. Clearing `index-pg-url` returns the index to SQLite; clearing legacy `index-backend` never changes selection. Notify fields clear the same way (`admin config clear notify-channel` disables routing). `admin config clear` removes the configuration file entry only; a PHASEGENT_* environment override still shadows the field until the environment is changed."
            );
        }
        "migrate" => print_admin_config_migrate_help(),
        _ => print_admin_config_help(role),
    }
}

/// `admin config migrate` page: the human-operator, lossless migration from a
/// legacy SQLite/TOML configuration into the JSONC configuration file.
fn print_admin_config_migrate_help() {
    println!(
        "Usage: phasegent admin config migrate --from-sqlite <ABSOLUTE PATH> [--from-toml <ABSOLUTE PATH>]\n\nHuman-operator only; AI roles must never invoke the admin group.\n\nMoves a legacy SQLite/TOML configuration into the JSONC configuration file and then purges the migrated rows from the legacy database.\n\nThe command reads the legacy configuration tables of the database at --from-sqlite, optionally folds the legacy TOML overlay at --from-toml over them (the TOML value wins for a field it defines), maps the result into the configuration document, and writes the destination file atomically as a create-only operation. It then re-reads the written file and compares it with the mapped values before touching the source. The legacy database is copied to a consistent backup that is created exclusively and owner-only, and the seven configuration tables are purged in a single transaction only after the source rows are re-read and confirmed unchanged. Business state in the legacy database (execution ledger, notification outbox, task bindings) is never read, copied into the file, or purged. The configuration file lock and a write transaction on the legacy database are held across the whole export, verification, backup, and purge, so nothing can change in between. The source must be corroborated as a known phasegent configuration database: its configuration tables must match a known schema variant, the known phasegent tables that are present must match their known shape, the source must carry a whole known phasegent table bundle, and its configuration tables must not carry a trigger or a foreign key; anything else is refused before a single row is deleted. The configuration file is read again right before the source is cleared: if it changed in the meantime, the migration stops and clears nothing. Stop every phasegent client and do not edit the configuration file while the command runs; the advisory lock only keeps cooperating phasegent writers out.\n\nThe destination is the JSONC configuration file: the absolute PHASEGENT_CONFIG_PATH when set, otherwise the ProjectDirs config_dir phasegent.jsonc. An existing destination with the same values is accepted and the purge resumes; a destination that already holds different values is refused and nothing is overwritten. A source without any configuration row is an explicit error unless an explicit TOML overlay supplies the values, in which case the overlay is migrated and the source is left as it is.\n\nThe report names the destination file, the backup file, and the migrated row counts. No configuration value and no credential is printed."
    );
}

/// `admin config provider` group page: human-operator provider writes plus the
/// shared resolver chain.
pub(crate) fn print_admin_config_provider_help(role: Option<Role>) {
    let role_text = role.map_or("ROLE", Role::as_str);
    println!(
        "Human-operator machine-wide default provider writes for {role_text}:\n\n  phasegent admin config provider set NAME  Validate and persist the default (redmine, local, forgejo, or gitlab)\n  phasegent admin config provider clear     Remove the persisted default so the resolver falls back to the role-scoped provider\n\nUsage: phasegent admin config provider <set NAME|clear>\n\nThe resolver precedence is: explicit --provider > PHASEGENT_PROVIDER (env) > PHASEGENT_DEFAULT_PROVIDER (env) > the persisted PHASEGENT_DEFAULT_PROVIDER in the configuration file > the role-scoped provider in the configuration file > redmine fallback. Writes go to the configuration file only."
    );
}

pub(crate) fn print_admin_config_provider_command_help(role: Option<Role>, command: &str) {
    match command {
        "set" => {
            println!(
                "Usage: phasegent admin config provider set <redmine|local|forgejo|gitlab>\n\nHuman-operator only; AI roles must never invoke the admin group.\n\nValidates NAME through ProviderKind::from_str and persists the result in the configuration file. Unknown literals return a structured config error before any write happens."
            );
        }
        "clear" => {
            println!(
                "Usage: phasegent admin config provider clear\n\nHuman-operator only; AI roles must never invoke the admin group.\n\nRemoves the PHASEGENT_DEFAULT_PROVIDER entry from the configuration file so the resolver falls back to the role-scoped provider. Returns {{\"cleared\": true}} when an entry existed or {{\"cleared\": false}} when the default was already absent."
            );
        }
        _ => print_admin_config_provider_help(role),
    }
}
